import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百三十五章 应该明白的事情","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/235第二百三十五章 应该明白的事情.md","filePath":"meditation/巴利文大藏经/235第二百三十五章 应该明白的事情.md"}'),_={name:"meditation/巴利文大藏经/235第二百三十五章 应该明白的事情.md"};function o(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百三十五章-应该明白的事情",tabindex:"-1"},[l("第二百三十五章 应该明白的事情 "),e("a",{class:"header-anchor",href:"#第二百三十五章-应该明白的事情","aria-label":'Permalink to "第二百三十五章 应该明白的事情"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应23经/遍知经(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！如来现在将要为你们讲说：什么是修行人应该完全理解和明白的事情？什么是只有证悟解脱果位的圣者才明白和理解的事情？你们要认真的听，你们要仔细的思考。”",-1),e("p",null,"出家弟子们回答：“世尊，我们会认真听您说法的，我们会仔细的思考的。恭请世尊您为我们说法。”",-1),e("p",null,"佛陀说：“物质事物、物质身体、感受、念想、行为、认识、分别、判断是修行人应该完全理解和明白的事情。它们的生起、形成、存续、发展、衰败、灭亡、消失是修行人应该完全理解和明白的事情。你们明白了缘起法（缘起法解释，见第四十八章、第四十九章），就能完全理解和明白物质事物、物质身体、感受、念想、行为、认识、分别、判断，就能完全理解和明白它们的生起、形成、存续、发展、衰败、灭亡、消失。这就是修行人应该完全理解和明白的事情。",-1),e("p",null,"比丘们！什么是只有证悟解脱果位的圣者才明白和理解的事情呢？那就是知道灭尽贪欲、愤怒、愚痴等等烦恼和痛苦的修行方法，也就是明白苦集灭道四圣谛，什么是苦集灭道四圣谛呢？就是出生在世间的众生是很痛苦的，痛苦的根源是贪爱，只有先灭除了贪爱才能灭除痛苦，而灭除痛苦的方法就是修习八正道（八正道解释，见第十八章），比丘们！这就是只有证悟解脱果位的圣者才明白和理解的事情。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(_,[["render",o]]);export{u as __pageData,f as default};
